<?php

namespace Modules\Finance\Services;
use Illuminate\Support\Facades\DB;use Modules\MasterData\Models\Currency;use RuntimeException;
class FxRateService{public function resolve(int$c,?int$currencyId,string$date,mixed$provided=null):float{$base=(string)DB::table('companies')->where('id',$c)->value('base_currency');if(!$currencyId){if($provided!==null&&abs((float)$provided-1)>0.000001)throw new RuntimeException('Dokumen base currency wajib menggunakan exchange rate 1.');return 1.0;}$currency=Currency::withoutGlobalScopes()->where('company_id',$c)->whereKey($currencyId)->first();if(!$currency)throw new RuntimeException('Currency tidak ditemukan pada company aktif.');if(strtoupper($currency->code)===strtoupper($base)){if($provided!==null&&abs((float)$provided-1)>0.000001)throw new RuntimeException('Base currency wajib menggunakan exchange rate 1.');return 1.0;}if($provided!==null){$rate=(float)$provided;if($rate<=0)throw new RuntimeException('Exchange rate wajib lebih besar dari nol.');return$rate;}$rate=$currency->rateAt($date);if(!$rate||$rate<=0)throw new RuntimeException("Exchange rate {$currency->code} belum tersedia pada {$date}.");return$rate;}}
